  'Workspace': 'កន្លែងធ្វើការ',
  'Log out': 'ចាកចេញ',
  'I have concerns about this person’s honesty or trustworthiness': 'ខ្ញុំមានការព្រួយបារម្ភអំពីភាពស្មោះត្រង់ ឬភាពគួរឱ្យទុកចិត្តរបស់មនុស្សនេះ',
  'I have seen a pattern of volatile anger from them': 'ខ្ញុំបានឃើញពួកគេខឹងងាយៗម្តងហើយម្តងទៀត',
  'I have seen a pattern of poor judgment or repeated bad decisions': 'ខ្ញុំបានឃើញពួកគេវិនិច្ឆ័យខុស ឬសម្រេចចិត្តមិនល្អម្តងហើយម្តងទៀត',
  'They are promising an unusually large reward for very little effort': 'ពួកគេសន្យាផលចំណេញធំខុសធម្មតា សម្រាប់ការខិតខំតិចតួច',
  'They rely on excessive flattery or high-pressure persuasion': 'ពួកគេពឹងលើការបញ្ជោរហួសហេតុ ឬការបង្ខំឱ្យយល់ព្រម',
  'They share other people’s private information inappropriately': 'ពួកគេចែករំលែកព័ត៌មានឯកជនរបស់អ្នកដទៃដោយមិនសមរម្យ',
  'They disregard agreements, rules, or boundaries': 'ពួកគេមិនគោរពកិច្ចព្រមព្រៀង ច្បាប់ ឬព្រំដែន',
  'Have I actually researched this, not just gone with my first instinct?': 'តើខ្ញុំបានស្រាវជ្រាវរឿងនេះពិតប្រាកដ មិនមែនគ្រាន់តែធ្វើតាមអារម្មណ៍ដំបូងទេឬ?',
  'Am I assuming today’s conditions will hold, rather than considering how things could change?': 'តើខ្ញុំសន្មតថាស្ថានភាពថ្ងៃនេះនឹងនៅដដែល ជាជាងគិតពីរបៀបដែលវាអាចផ្លាស់ប្តូរឬ?',
  'Have I verified the key claims myself, rather than taking them at face value?': 'តើខ្ញុំបានផ្ទៀងផ្ទាត់ការអះអាងសំខាន់ៗដោយខ្លួនឯង ជាជាងជឿតាមសម្តីឬ?',
  'Am I judging this by substance, not just how polished or confident it looks?': 'តើខ្ញុំវិនិច្ឆ័យរឿងនេះតាមខ្លឹមសារ មិនមែនតាមរូបរាងស្អាត ឬភាពជឿជាក់ខាងក្រៅទេឬ?',
  'Am I deciding on my own timeline, rather than because someone is rushing me?': 'តើខ្ញុំសម្រេចចិត្តតាមពេលវេលារបស់ខ្ញុំ មិនមែនដោយសារមានគេប្រញាប់ខ្ញុំទេឬ?',
  'Have I talked this through with someone outside my own head?': 'តើខ្ញុំបានពិភាក្សារឿងនេះជាមួយអ្នកផ្សេងហើយឬនៅ?',
  'Does the reward here match the effort, rather than looking too easy?': 'តើផលចំណេញនេះសមនឹងការខិតខំ មិនមែនមើលទៅងាយពេកទេឬ?',
  'Am I still willing to hear advice that disagrees with what I want to do?': 'តើខ្ញុំនៅតែព្រមស្តាប់ដំបូន្មានដែលមិនយល់ស្របនឹងអ្វីដែលខ្ញុំចង់ធ្វើឬ?',
  'Avoided attacking character or name-calling': 'ជៀសវាងការវាយប្រហារលើចរិត ឬការជេរប្រមាថ',
  'Stayed on this specific incident, not past ones': 'និយាយតែពីហេតុការណ៍នេះ មិនលើករឿងចាស់',
  'Avoided threats, ultimatums, or sarcasm': 'ជៀសវាងការគំរាម ការដាក់លក្ខខណ្ឌចុងក្រោយ ឬការនិយាយចំអក',
  'Named an outcome that works for both sides, not just one': 'បានលើកលទ្ធផលដែលល្អសម្រាប់ភាគីទាំងពីរ មិនមែនតែម្ខាង',
