  'Needs your attention': 'ត្រូវការការយកចិត្តទុកដាក់',
  'Places where the map has a dead end — nothing below can move until these are fixed': 'កន្លែងដែលផែនទីជាប់គាំង — គ្មានអ្វីនៅខាងក្រោមអាចដំណើរការបានទេ រហូតដល់ដោះស្រាយចំណុចទាំងនេះ',
  'Blocked tasks with no partner': 'កិច្ចការជាប់គាំងដែលគ្មានដៃគូ',
  'Find a partner': 'រកដៃគូ',
