  'Give it attention': 'យកចិត្តទុកដាក់លើវា',
  'Moonshots not started': 'Moonshot ដែលមិនទាន់ចាប់ផ្តើម',
  'Start or revise': 'ចាប់ផ្តើម ឬកែសម្រួល',
  'Moonshot dreams still an idea': 'ក្តីស្រមៃ Moonshot ដែលនៅជាគំនិតនៅឡើយ',
  'Nothing is lined up to unblock these. They will stay stuck until someone helps.': 'គ្មានអ្វីត្រៀមដើម្បីដោះគាំងទាំងនេះទេ។ វានឹងនៅជាប់គាំង រហូតដល់មាននរណាម្នាក់ជួយ។',
  'A step marked complex has nothing to actually do. There is no first action to take.': 'ជំហានដែលសម្គាល់ថាស្មុគស្មាញ មិនមានអ្វីត្រូវធ្វើពិតប្រាកដទេ។ គ្មានសកម្មភាពដំបូងត្រូវធ្វើ។',
  'A dream with no goals is still a wish — nothing can be executed on it.': 'ក្តីស្រមៃដែលគ្មានគោលដៅ នៅតែជាបំណងប្រាថ្នា — មិនអាចអនុវត្តអ្វីបានទេ។',
  'This goal has no path to it yet.': 'គោលដៅនេះមិនទាន់មានផ្លូវទៅដល់នៅឡើយទេ។',
  'Active goals here, but nothing has moved in two weeks while other areas did. Give it attention this week, or pause it on purpose.': 'មានគោលដៅសកម្មនៅទីនេះ ប៉ុន្តែគ្មានអ្វីរីកចម្រើនក្នុងរយៈពេលពីរសប្តាហ៍ ខណៈផ្នែកផ្សេងទៀតរីកចម្រើន។ យកចិត្តទុកដាក់លើវាសប្តាហ៍នេះ ឬផ្អាកវាដោយចេតនា។',
  'Ambition going stale — start the first step, or consciously revise the goal.': 'មហិច្ឆតាកំពុងរសាត់ — ចាប់ផ្តើមជំហានដំបូង ឬកែសម្រួលគោលដៅដោយដឹងខ្លួន។',
  'A moonshot that never left the idea stage is ambition going stale — promote it to active, or consciously revise it.': 'Moonshot ដែលមិនដែលចេញពីដំណាក់កាលគំនិត គឺជាមហិច្ឆតាកំពុងរសាត់ — ដាក់វាឱ្យសកម្ម ឬកែសម្រួលវាដោយដឹងខ្លួន។',
  'Every dream has goals, every goal has steps, every complex step has tasks, and nothing is blocked without someone to unblock it.': 'ក្តីស្រមៃនីមួយៗមានគោលដៅ គោលដៅនីមួយៗមានជំហាន ជំហានស្មុគស្មាញនីមួយៗមានកិច្ចការ ហើយគ្មានអ្វីជាប់គាំងដោយគ្មានអ្នកជួយដោះស្រាយទេ។',
  'No data yet.': 'មិនទាន់មានទិន្នន័យទេ។',
