  'Overdue Tasks': 'កិច្ចការហួសកំណត់',
  'Blocked Tasks': 'កិច្ចការជាប់គាំង',
  'Portfolio overview': 'ទិដ្ឋភាពទូទៅ',
  'Active Dreams': 'ក្តីស្រមៃសកម្ម',
