  'Average Progress': 'វឌ្ឍនភាពមធ្យម',
  'No tasks due this week — nothing to weigh yet.': 'គ្មានកិច្ចការដល់កំណត់សប្តាហ៍នេះទេ — មិនទាន់មានអ្វីត្រូវថ្លឹងថ្លែង។',
  'Balanced — charging and draining work are even this week.': 'មានតុល្យភាព — ការងារបញ្ចូលថាមពល និងការងារធ្វើឱ្យអស់កម្លាំងស្មើគ្នាសប្តាហ៍នេះ។',
  'Energy budget': 'ថវិកាថាមពល',
  'This week\'s tasks by energy demand — charging work weighed against draining work': 'កិច្ចការសប្តាហ៍នេះតាមតម្រូវការថាមពល — ការងារបញ្ចូលថាមពលធៀបនឹងការងារធ្វើឱ្យអស់កម្លាំង',
  'Get started': 'ចាប់ផ្តើម',
  'Create a Vision Area': 'បង្កើតផ្នែកចក្ខុវិស័យ',
  'A major area of your life or work — like Career, Health, or Family.': 'ផ្នែកធំមួយនៃជីវិត ឬការងាររបស់អ្នក — ដូចជា អាជីព សុខភាព ឬគ្រួសារ។',
