  'A meaningful outcome you want to reach. A short guide helps you make it clear.': 'លទ្ធផលដែលមានអត្ថន័យដែលអ្នកចង់សម្រេច។ មគ្គុទ្ទេសក៍ខ្លីមួយជួយអ្នកធ្វើឱ្យវាច្បាស់។',
  'Break it down': 'បំបែកវា',
  'Turn the dream into goals, steps, and tasks on the Vision Map.': 'ប្រែក្តីស្រមៃទៅជាគោលដៅ ជំហាន និងកិច្ចការនៅលើផែនទីចក្ខុវិស័យ។',
  'Create a vision area': 'បង្កើតផ្នែកចក្ខុវិស័យ',
  'Add a dream': 'បន្ថែមក្តីស្រមៃ',
