  'Three steps from a blank page to a plan. This checklist disappears once your first dream has goals.': 'បីជំហានពីទំព័រទទេទៅផែនការ។ បញ្ជីនេះនឹងបាត់ ពេលក្តីស្រមៃដំបូងរបស់អ្នកមានគោលដៅ។',
  'Nothing logged yet — the first entry starts the list.': 'មិនទាន់មានកំណត់ត្រាទេ — កំណត់ត្រាដំបូងចាប់ផ្តើមបញ្ជី។',
