  'Describe the finish line so clearly you could recognize the day you cross it.': 'ពណ៌នាគោលដៅចុងក្រោយឱ្យច្បាស់ ដល់កម្រិតដែលអ្នកអាចស្គាល់ថ្ងៃដែលអ្នកឆ្លងកាត់វា។',
