  'Aim for 2–4 goals; each one becomes steps and tasks on the Vision Map.': 'ព្យាយាមឱ្យមាន 2–4 គោលដៅ។ នីមួយៗក្លាយជាជំហាន និងកិច្ចការនៅលើផែនទីចក្ខុវិស័យ។',
  'e.g. Become a confident public speaker': 'ឧ. ក្លាយជាអ្នកនិយាយជាសាធារណៈដែលមានទំនុកចិត្ត',
