  'Optional, but writing this down first makes every dream you add underneath easier to judge — does it actually move you toward this, or not?': 'មិនចាំបាច់ ប៉ុន្តែការសរសេរវាជាមុន ធ្វើឱ្យងាយវាយតម្លៃក្តីស្រមៃនីមួយៗដែលអ្នកបន្ថែមនៅខាងក្រោម — តើវាពិតជានាំអ្នកឆ្ពោះទៅរកវាឬទេ?',
