  'A dream is the meaningful outcome everything else builds toward — create one and the map grows from there.': 'ក្តីស្រមៃគឺជាលទ្ធផលដែលមានអត្ថន័យ ដែលអ្វីៗផ្សេងទៀតកសាងឆ្ពោះទៅរក — បង្កើតមួយ ហើយផែនទីនឹងរីកធំពីទីនោះ។',
  'Make this dream clearer': 'ធ្វើឱ្យក្តីស្រមៃនេះច្បាស់ជាងមុន',
  'A vague dream is hard to turn into goals. Answer these before saving:': 'ក្តីស្រមៃមិនច្បាស់ ពិបាកប្រែទៅជាគោលដៅ។ ឆ្លើយសំណួរទាំងនេះមុនរក្សាទុក៖',
