  'View goals': 'មើលគោលដៅ',
  'Order': 'លំដាប់',
  'Code': 'លេខកូដ',
  'Target': 'គោលដៅ',
  'Action': 'សកម្មភាព',
  'Unable to update dream status.': 'មិនអាចធ្វើបច្ចុប្បន្នភាពស្ថានភាពក្តីស្រមៃបានទេ។',
  'Unable to reorder dreams.': 'មិនអាចរៀបលំដាប់ក្តីស្រមៃឡើងវិញបានទេ។',
  'A goal runs past this dream\'s fixed target date.': 'មានគោលដៅមួយហួសកាលបរិច្ឆេទគោលដៅថេររបស់ក្តីស្រមៃនេះ។',
  'A real external deadline that cannot move. Goals running past it are flagged, not blocked.': 'ថ្ងៃកំណត់ពិតពីខាងក្រៅដែលមិនអាចផ្លាស់ប្តូរ។ គោលដៅដែលហួសវានឹងត្រូវសម្គាល់ មិនមែនហាមឃាត់ទេ។',
  'No dreams match these filters.': 'គ្មានក្តីស្រមៃត្រូវនឹងតម្រងទាំងនេះទេ។',
  'No dreams yet.': 'មិនទាន់មានក្តីស្រមៃទេ។',
  'Optional. A, B, C… — assigned after listing everything, to mark which dreams in this area come first. Ties are fine; nothing enforces a unique order.': 'មិនចាំបាច់។ A, B, C… — ដាក់ក្រោយពីរាយអ្វីៗទាំងអស់ ដើម្បីសម្គាល់ថាក្តីស្រមៃណាក្នុងផ្នែកនេះមកមុន។ ស្មើគ្នាក៏បាន គ្មានអ្វីបង្ខំឱ្យលំដាប់ខុសគ្នាទេ។',
  'If resources were no limit, what would the ideal result look like? Aim beyond what feels achievable — this is aspirational only and never changes the dream\'s progress or completion.': 'បើធនធានគ្មានដែនកំណត់ តើលទ្ធផលល្អបំផុតមានរូបរាងបែបណា? តម្រង់ហួសពីអ្វីដែលហាក់អាចសម្រេចបាន — នេះគ្រាន់តែជាសេចក្តីប្រាថ្នា មិនប៉ះពាល់វឌ្ឍនភាព ឬការបញ្ចប់ក្តីស្រមៃទេ។',
  'Optional. A link to a picture of what achieving this dream looks like — no upload, just paste a link to an image hosted elsewhere.': 'មិនចាំបាច់។ តំណទៅរូបភាពនៃការសម្រេចក្តីស្រមៃនេះ — មិនចាំបាច់ផ្ទុកឡើងទេ គ្រាន់តែបិទភ្ជាប់តំណរូបភាពដែលមាននៅកន្លែងផ្សេង។',
  'This is a high-priority moonshot dream. Answer all eight questions honestly, or instead link at least two Advisor or Mentor partners to it (directly or through one of its goals) on the Partners page. Either one clears this check — there\'s no right answer here, only an honest one.': 'នេះជាក្តីស្រមៃ Moonshot អាទិភាពខ្ពស់។ ឆ្លើយសំណួរទាំងប្រាំបីដោយស្មោះ ឬភ្ជាប់ដៃគូជាទីប្រឹក្សា ឬអ្នកណែនាំយ៉ាងហោចណាស់ពីរនាក់ទៅវា (ដោយផ្ទាល់ ឬតាមគោលដៅមួយរបស់វា) នៅទំព័រដៃគូ។ មួយណាក៏ឆ្លងការត្រួតពិនិត្យនេះបាន — គ្មានចម្លើយត្រូវ ឬខុសទេ មានតែចម្លើយស្មោះត្រង់។',
  'Overdue only': 'តែហួសកំណត់',
  'Moonshots only': 'តែ Moonshot',
  'A dream is a meaningful outcome you want to reach — the guide asks a few questions to make it clear enough to plan.': 'ក្តីស្រមៃគឺជាលទ្ធផលដែលមានអត្ថន័យដែលអ្នកចង់សម្រេច — មគ្គុទ្ទេសក៍សួរសំណួរពីរបី ដើម្បីធ្វើឱ្យវាច្បាស់ល្មមអាចរៀបផែនការបាន។',
  'Create goal': 'បង្កើតគោលដៅ',
  'Create a dream first': 'បង្កើតក្តីស្រមៃជាមុនសិន',
  'Create your first goal': 'បង្កើតគោលដៅដំបូងរបស់អ្នក',
