  'Optional. A, B, C… — assigned after listing everything, to mark which areas come first. Ties are fine; nothing enforces a unique order.': 'មិនចាំបាច់។ A, B, C… — ដាក់ក្រោយពីរាយអ្វីៗទាំងអស់ ដើម្បីសម្គាល់ថាផ្នែកណាមកមុន។ ស្មើគ្នាក៏បាន គ្មានអ្វីបង្ខំឱ្យលំដាប់ខុសគ្នាទេ។',
  'What does this area look like when it\'s going well? Optional, but writing it down first makes the dreams underneath it easier to judge.': 'តើផ្នែកនេះមានរូបរាងបែបណា ពេលវាដំណើរការល្អ? មិនចាំបាច់ ប៉ុន្តែការសរសេរវាជាមុន ធ្វើឱ្យងាយវាយតម្លៃក្តីស្រមៃនៅខាងក្រោមវា។',
