  'Due {period}': 'ដល់កំណត់{period}',
  'Completed {period}': 'បានបញ្ចប់{period}',
  '{count} logged this week — what\'s already going well, not just what\'s unfinished': 'បានកត់ត្រា {count} សប្តាហ៍នេះ — អ្វីដែលកំពុងដំណើរការល្អ មិនមែនតែអ្វីដែលមិនទាន់រួចទេ',
  'Archiving "{title}" also archives {goals} goal(s), {steps} step(s), and {tasks} task(s). Everything can be restored later with "Show archived".': 'ការទុក «{title}» ក្នុងបណ្ណសារ ក៏ទុកគោលដៅ {goals} ជំហាន {steps} និងកិច្ចការ {tasks} ផងដែរ។ អ្វីៗទាំងអស់អាចស្ដារវិញពេលក្រោយតាម «បង្ហាញអ្វីដែលក្នុងបណ្ណសារ»។',
  'Archiving "{title}" also archives {steps} step(s) and {tasks} task(s). Everything can be restored later with "Show archived".': 'ការទុក «{title}» ក្នុងបណ្ណសារ ក៏ទុកជំហាន {steps} និងកិច្ចការ {tasks} ផងដែរ។ អ្វីៗទាំងអស់អាចស្ដារវិញពេលក្រោយតាម «បង្ហាញអ្វីដែលក្នុងបណ្ណសារ»។',
  'Archiving "{title}" also archives {tasks} task(s). Everything can be restored later with "Show archived".': 'ការទុក «{title}» ក្នុងបណ្ណសារ ក៏ទុកកិច្ចការ {tasks} ផងដែរ។ អ្វីៗទាំងអស់អាចស្ដារវិញពេលក្រោយតាម «បង្ហាញអ្វីដែលក្នុងបណ្ណសារ»។',
  'Archiving "{title}" also archives {dreams} dream(s), {goals} goal(s), {steps} step(s), and {tasks} task(s). Everything can be restored later with "Show archived".': 'ការទុក «{title}» ក្នុងបណ្ណសារ ក៏ទុកក្តីស្រមៃ {dreams} គោលដៅ {goals} ជំហាន {steps} និងកិច្ចការ {tasks} ផងដែរ។ អ្វីៗទាំងអស់អាចស្ដារវិញពេលក្រោយតាម «បង្ហាញអ្វីដែលក្នុងបណ្ណសារ»។',
