  'G-001 · updated just now': 'G-001 · ទើបធ្វើបច្ចុប្បន្នភាព',
  'Choose how the app looks. Changes apply immediately and are saved to your account.': 'ជ្រើសរូបរាងកម្មវិធី។ ការផ្លាស់ប្តូរមានប្រសិទ្ធភាពភ្លាមៗ ហើយរក្សាទុកក្នុងគណនីរបស់អ្នក។',
  'Changes the shape of the app — corners, shadows, and navigation — not its colours. Works with every theme above.': 'ផ្លាស់ប្តូររាងកម្មវិធី — ជ្រុង ស្រមោល និងការរុករក — មិនមែនពណ៌ទេ។ ប្រើបានជាមួយរចនាប័ទ្មទាំងអស់ខាងលើ។',
  'System follows your device setting and updates when it changes.': '«តាមប្រព័ន្ធ» ធ្វើតាមការកំណត់ឧបករណ៍របស់អ្នក ហើយប្តូរពេលវាផ្លាស់ប្តូរ។',
  'Every accent is checked for readable contrast in both light and dark.': 'ពណ៌សង្កត់នីមួយៗត្រូវបានពិនិត្យឱ្យមានកម្រិតពណ៌អាចអានបាន ទាំងភ្លឺ និងងងឹត។',
  'Background image': 'រូបភាពផ្ទៃខាងក្រោយ',
  'Current background image': 'រូបភាពផ្ទៃខាងក្រោយបច្ចុប្បន្ន',
  'Compact fits more rows on screen without hiding anything.': '«ណែន» ដាក់ជួរបានច្រើនលើអេក្រង់ ដោយមិនលាក់អ្វីទេ។',
  'The default is your device\'s own font and loads instantly. The others download once, the first time you pick them.': 'លំនាំដើមគឺពុម្ពអក្សររបស់ឧបករណ៍អ្នក ហើយផ្ទុកភ្លាមៗ។ ពុម្ពផ្សេងទៀតទាញយកម្តង នៅពេលអ្នកជ្រើសវាលើកដំបូង។',
  'Scales all text proportionally, unlike browser zoom.': 'ពង្រីកអក្សរទាំងអស់តាមសមាមាត្រ ខុសពីការពង្រីករបស់កម្មវិធីរុករក។',
  'These work with any theme above — they don\'t replace your choice.': 'ទាំងនេះប្រើបានជាមួយរចនាប័ទ្មណាមួយខាងលើ — វាមិនជំនួសជម្រើសរបស់អ្នកទេ។',
  'Focus mode': 'របៀបផ្តោតអារម្មណ៍',
  'Unavailable while high contrast is on — it uses pure white or black surfaces.': 'មិនអាចប្រើបានពេលកម្រិតពណ៌ខ្ពស់បើក — វាប្រើផ្ទៃសសុទ្ធ ឬខ្មៅសុទ្ធ។',
  'Changes the page, cards, and sidebar together.': 'ផ្លាស់ប្តូរទំព័រ កាត និងរបារចំហៀងព្រមគ្នា។',
  'Paused while high contrast is on — the image is removed so text stays maximally legible. It comes back when high contrast is switched off.': 'ផ្អាកពេលកម្រិតពណ៌ខ្ពស់បើក — រូបភាពត្រូវដកចេញ ដើម្បីឱ្យអក្សរអានបានច្បាស់បំផុត។ វានឹងត្រឡប់មកវិញពេលបិទកម្រិតពណ៌ខ្ពស់។',
  'Your own picture behind the app — stored on this device only, never uploaded. A wash of the page colour keeps text readable.': 'រូបភាពផ្ទាល់ខ្លួនរបស់អ្នកនៅពីក្រោយកម្មវិធី — រក្សាទុកតែលើឧបករណ៍នេះ មិនដែលផ្ទុកឡើងទេ។ ស្រទាប់ពណ៌ទំព័រធ្វើឱ្យអក្សរអាចអានបាន។',
