  'Summarize key findings': 'សង្ខេបលទ្ធផលសំខាន់ៗ',
  'That image is too large even after compression — try a smaller one.': 'រូបភាពនោះធំពេក ទោះបីបង្រួមហើយក៏ដោយ — សាកល្បងរូបតូចជាងនេះ។',
  'Could not read that file as an image.': 'មិនអាចអានឯកសារនោះជារូបភាពបានទេ។',
  'Your settings don\'t match a preset, so they\'re shown as Custom. Pick a preset above to go back to one.': 'ការកំណត់របស់អ្នកមិនត្រូវនឹងគំរូណាមួយទេ ដូច្នេះបង្ហាញជា «ផ្ទាល់ខ្លួន»។ ជ្រើសគំរូមួយខាងលើ ដើម្បីត្រឡប់ទៅវិញ។',
  'Stronger text, borders, and focus rings.': 'អក្សរ ស៊ុម និងរង្វង់ផ្តោតកាន់តែដិត។',
  'Turns off animations. If your device already asks for reduced motion, that still applies.': 'បិទចលនា។ ប្រសិនបើឧបករណ៍របស់អ្នកស្នើកាត់បន្ថយចលនារួចហើយ ការកំណត់នោះនៅតែមានប្រសិទ្ធភាព។',
  'Real components, not mock-ups — this is how your data will look.': 'សមាសធាតុពិត មិនមែនគំរូទេ — នេះជារបៀបដែលទិន្នន័យរបស់អ្នកនឹងបង្ហាញ។',
  'Goal under Career Development · target 30 Sep': 'គោលដៅក្រោមការអភិវឌ្ឍអាជីព · គោលដៅ 30 កញ្ញា',
  'None': 'គ្មាន',
  'Optional. The pushback you expect, and how you\'d answer it.': 'មិនចាំបាច់។ ការជំទាស់ដែលអ្នករំពឹង និងរបៀបដែលអ្នកនឹងឆ្លើយ។',
