  'Open with something specific to them, not a generic greeting. Try one of: a genuine question about their work; a shared connection or moment ("We met at..."); or a concrete result you admire ("Your talk on X changed how I...").': 'ចាប់ផ្តើមដោយអ្វីដែលជាក់លាក់ចំពោះពួកគេ មិនមែនការស្វាគមន៍ទូទៅទេ។ សាកល្បងមួយក្នុងចំណោម៖ សំណួរពិតប្រាកដអំពីការងាររបស់ពួកគេ ទំនាក់ទំនង ឬពេលវេលារួម («យើងបានជួបគ្នានៅ...») ឬលទ្ធផលជាក់ស្តែងដែលអ្នកកោតសរសើរ («បទបង្ហាញរបស់អ្នកអំពី X បានផ្លាស់ប្តូររបៀបដែលខ្ញុំ...»)។',
