  'A "No" here never blocks anything — only leaving one unanswered does, and only for a Resolved transition.': 'ចម្លើយ «ទេ» នៅទីនេះមិនដែលរារាំងអ្វីទេ — មានតែការទុកសំណួរមិនឆ្លើយទេដែលរារាំង ហើយតែពេលប្តូរទៅ «បានដោះស្រាយ» ប៉ុណ្ណោះ។',
