  'Expectation released — a one-time marker, and it doesn\'t change anything else about this obstacle.': 'បានដោះលែងការរំពឹង — ជាសញ្ញាសម្គាល់តែម្តង ហើយវាមិនផ្លាស់ប្តូរអ្វីផ្សេងទៀតនៃឧបសគ្គនេះទេ។',
