  'Check anything that concerns you. If nothing does, moving to Active needs no extra step. If something does, you\'ll need to record why you\'re proceeding anyway.': 'គូសធីកអ្វីដែលធ្វើឱ្យអ្នកព្រួយបារម្ភ។ បើគ្មាន ការប្តូរទៅសកម្មមិនត្រូវការជំហានបន្ថែមទេ។ បើមាន អ្នកត្រូវកត់ត្រាហេតុអ្វីអ្នកនៅតែបន្ត។',
