  'Your answers were close enough that this style shows up too — most people are a blend.': 'ចម្លើយរបស់អ្នកជិតគ្នាល្មម ដែលរបៀបនេះក៏បង្ហាញដែរ — មនុស្សភាគច្រើនជាការលាយបញ្ចូលគ្នា។',
