  'Steadier': 'អ្នកនឹងនរ',
  'Planner': 'អ្នករៀបផែនការ',
  'Decides fast and drives work toward a concrete result without waiting for perfect conditions.': 'សម្រេចចិត្តរហ័ស ហើយជំរុញការងារឆ្ពោះទៅលទ្ធផលជាក់ស្តែង ដោយមិនរង់ចាំលក្ខខណ្ឌល្អឥតខ្ចោះ។',
  'Detail and follow-through can get skipped in the rush to the next thing.': 'ព័ត៌មានលម្អិត និងការធ្វើឱ្យដល់ទីបញ្ចប់ អាចត្រូវរំលង ពេលប្រញាប់ទៅរឿងបន្ទាប់។',
  'Lead with the bottom line and the decision you need — save the background for if they ask.': 'ចាប់ផ្តើមដោយចំណុចសំខាន់ និងការសម្រេចចិត្តដែលអ្នកត្រូវការ — ទុកព័ត៌មានផ្ទៃខាងក្រោយ សម្រាប់ពេលពួកគេសួរ។',
  'Builds momentum and relationships quickly, and gets people energized to start.': 'កសាងសន្ទុះ និងទំនាក់ទំនងបានរហ័ស ហើយធ្វើឱ្យមនុស្សមានថាមពលចាប់ផ្តើម។',
  'Initial energy can outrun follow-through once the work turns routine.': 'ថាមពលដំបូងអាចលឿនជាងការធ្វើឱ្យដល់ទីបញ្ចប់ ពេលការងារក្លាយជាទម្លាប់។',
  'Pair enthusiasm with one specific, dated commitment so momentum has something to land on.': 'ភ្ជាប់ភាពរំភើបជាមួយការប្តេជ្ញាជាក់លាក់មួយដែលមានកាលបរិច្ឆេទ ដើម្បីឱ្យសន្ទុះមានទីពឹង។',
  'Patient, loyal, and steady — the person work can depend on staying done once it is.': 'អត់ធ្មត់ ស្មោះត្រង់ និងនឹងនរ — មនុស្សដែលការងារអាចពឹងផ្អែកបាន ថានឹងនៅរួចរាល់ពេលធ្វើរួច។',
  'Can be slow to push a decision or initiative forward under time pressure.': 'អាចយឺតក្នុងការជំរុញការសម្រេចចិត្ត ឬគំនិតផ្តួចផ្តើម ពេលមានសម្ពាធពេលវេលា។',
  'Acknowledge the relationship first, then be direct about the ask — avoid burying it.': 'ទទួលស្គាល់ទំនាក់ទំនងជាមុន រួចនិយាយត្រង់អំពីសំណើ — កុំលាក់វា។',
  'Systematic and detail-oriented, catching what a faster pass would miss.': 'មានប្រព័ន្ធ និងយកចិត្តទុកដាក់លម្អិត ចាប់បានអ្វីដែលការមើលរហ័សនឹងរំលង។',
  'Deliberation can run long, and the human side of a request can feel like an afterthought.': 'ការពិចារណាអាចយូរ ហើយផ្នែកមនុស្សនៃសំណើអាចហាក់ដូចជារឿងបន្ទាប់បន្សំ។',
  'Bring the plan and the data, but expect to be pushed on committing to a date sooner than feels ready.': 'យកផែនការ និងទិន្នន័យមក ប៉ុន្តែរំពឹងថានឹងត្រូវជំរុញឱ្យប្តេជ្ញាលើកាលបរិច្ឆេទ លឿនជាងពេលដែលអ្នកមានអារម្មណ៍ថាត្រៀមរួច។',
