  'Quotes each person\'s own "why it matters". Only for people who gave AI consent. Each email is one AI request, about $0.005.': 'ដកស្រង់ "ហេតុអ្វីវាសំខាន់" ផ្ទាល់ខ្លួនរបស់មនុស្សម្នាក់ៗ។ សម្រាប់តែអ្នកដែលបានយល់ព្រមលើ AI។ អ៊ីមែលនីមួយៗជាសំណើ AI មួយ ប្រហែល $0.005។',
