  'An example (about someone else)': 'ឧទាហរណ៍ (អំពីអ្នកផ្សេង)',
  'No draft this time. Try Help me start instead.': 'លើកនេះគ្មានសេចក្តីព្រាងទេ។ សាកល្បង ជួយខ្ញុំចាប់ផ្តើម ជំនួសវិញ។',
  'Put this draft in the form': 'ដាក់សេចក្តីព្រាងនេះក្នុងទម្រង់',
  'The draft is in the form below. Edit it until it is truly yours, then save the exercise.': 'សេចក្តីព្រាងនៅក្នុងទម្រង់ខាងក្រោម។ កែវារហូតដល់វាពិតជារបស់អ្នក រួចរក្សាទុកលំហាត់។',
  'What does my result mean?': 'តើលទ្ធផលរបស់ខ្ញុំមានន័យដូចម្តេច?',
  'A plain explanation of your latest scores, and where to focus next.': 'ការពន្យល់ងាយៗអំពីពិន្ទុចុងក្រោយរបស់អ្នក និងកន្លែងដែលត្រូវផ្តោតបន្ទាប់។',
  'Explain my result': 'ពន្យល់លទ្ធផលរបស់ខ្ញុំ',
  'Focus next:': 'ផ្តោតបន្ទាប់៖',
  'This module is done elsewhere in the app, so there is no form to draft. Ask for help to start instead.': 'ម៉ូឌុលនេះធ្វើនៅកន្លែងផ្សេងក្នុងកម្មវិធី ដូច្នេះគ្មានទម្រង់សម្រាប់ព្រាងទេ។ សូមសុំជំនួយដើម្បីចាប់ផ្តើមជំនួសវិញ។',
  'Write something in the exercise first, then ask for feedback.': 'សូមសរសេរអ្វីមួយក្នុងលំហាត់ជាមុនសិន រួចសុំមតិ។',
  'Take the assessment first, then ask for an explanation.': 'សូមធ្វើការវាយតម្លៃជាមុនសិន រួចសុំការពន្យល់។',
  'This action is not supported here.': 'សកម្មភាពនេះមិនត្រូវបានគាំទ្រនៅទីនេះទេ។',
  // V9 Phase 8: coach co-pilot
  'Finished {now} item(s) this week, down from {before} the week before.': 'បានបញ្ចប់ {now} ក្នុងសប្តាហ៍នេះ ធ្លាក់ពី {before} កាលពីសប្តាហ៍មុន។',
  '{count} step(s) overdue again after being given a new date.': 'ជំហាន {count} ហួសកាលកំណត់ម្តងទៀត បន្ទាប់ពីបានទទួលកាលបរិច្ឆេទថ្មី។',
  '{count} items overdue.': 'ធាតុ {count} ហួសកាលកំណត់។',
