  'Progress, mood, risks and one suggested action, from what you may see of this participant.': 'វឌ្ឍនភាព អារម្មណ៍ ហានិភ័យ និងសកម្មភាពដែលបានណែនាំមួយ ពីអ្វីដែលអ្នកអាចមើលឃើញអំពីអ្នកចូលរួមនេះ។',
  'This participant has not turned on AI consent, so AI cannot read their plan.': 'អ្នកចូលរួមនេះមិនទាន់បើកការយល់ព្រមលើ AI ទេ ដូច្នេះ AI មិនអាចអានផែនការរបស់ពួកគេបានទេ។',
