  'Check and edit before you send. Nothing is sent until you click Send comment.': 'សូមពិនិត្យ និងកែមុនពេលផ្ញើ។ គ្មានអ្វីត្រូវបានផ្ញើទេ រហូតដល់អ្នកចុច ផ្ញើមតិ។',
  'No one in this cohort has turned on AI consent yet.': 'មិនទាន់មាននរណាម្នាក់ក្នុងក្រុមសិក្សានេះបើកការយល់ព្រមលើ AI នៅឡើយទេ។',
  // V9 Phase 9: admin AI
  'Approved resources': 'ធនធានដែលបានអនុម័ត',
  'Resources you have checked. AI resource ideas use these first, and only these can show a link.': 'ធនធានដែលអ្នកបានពិនិត្យ។ គំនិតធនធានពី AI ប្រើទាំងនេះមុនគេ ហើយមានតែទាំងនេះទេដែលអាចបង្ហាញតំណ។',
  'No approved resources yet.': 'មិនទាន់មានធនធានដែលបានអនុម័តទេ។',
