  'Program coaching guidelines (optional)': 'គោលការណ៍ណែនាំការបង្វឹករបស់កម្មវិធី (ជាជម្រើស)',
  'Added to the built-in guidelines, for example your program\'s tone or local examples. The built-in safety rules always apply and cannot be turned off here. Try a few conversations after a change.': 'បន្ថែមលើគោលការណ៍ណែនាំដែលមានស្រាប់ ឧទាហរណ៍ សំនៀងរបស់កម្មវិធី ឬឧទាហរណ៍ក្នុងស្រុក។ ច្បាប់សុវត្ថិភាពដែលមានស្រាប់តែងតែអនុវត្ត ហើយមិនអាចបិទនៅទីនេះបានទេ។ សូមសាកល្បងការសន្ទនាមួយចំនួនបន្ទាប់ពីផ្លាស់ប្តូរ។',
  'AI help is on for this cohort': 'ជំនួយ AI បើកសម្រាប់ក្រុមសិក្សានេះ',
  'AI help is off for this cohort': 'ជំនួយ AI បិទសម្រាប់ក្រុមសិក្សានេះ',
  'AI is switched off for this participant\'s cohort.': 'AI ត្រូវបានបិទសម្រាប់ក្រុមសិក្សារបស់អ្នកចូលរួមនេះ។',
  'AI is switched off for this cohort.': 'AI ត្រូវបានបិទសម្រាប់ក្រុមសិក្សានេះ។',
  'AI help for this text': 'ជំនួយ AI សម្រាប់អត្ថបទនេះ',
  'What should change? (optional)': 'តើគួរផ្លាស់ប្តូរអ្វី? (ជាជម្រើស)',
  'Translate from English with AI': 'បកប្រែពីភាសាអង់គ្លេសជាមួយ AI',
  'The Khmer draft is in the form. Have a Khmer speaker check it before you save.': 'សេចក្តីព្រាងភាសាខ្មែរនៅក្នុងទម្រង់។ សូមឱ្យអ្នកនិយាយភាសាខ្មែរពិនិត្យមុនពេលរក្សាទុក។',
  'The draft is in the form. Read it through, then save the module.': 'សេចក្តីព្រាងនៅក្នុងទម្រង់។ សូមអានឱ្យចប់ រួចរក្សាទុកម៉ូឌុល។',
  'Put this text in the form': 'ដាក់អត្ថបទនេះក្នុងទម្រង់',
  'Examples': 'ឧទាហរណ៍',
  'Quiz questions': 'សំណួរតេស្ត',
  'The app has no quiz yet; copy these into your teaching material.': 'កម្មវិធីមិនទាន់មានតេស្តនៅឡើយទេ សូមចម្លងទាំងនេះទៅក្នុងឯកសារបង្រៀនរបស់អ្នក។',
  'Suggest Khmer': 'ណែនាំភាសាខ្មែរ',
  'No usable draft this time. Try again, or write it yourself.': 'លើកនេះគ្មានសេចក្តីព្រាងដែលអាចប្រើបានទេ។ សូមព្យាយាមម្តងទៀត ឬសរសេរដោយខ្លួនឯង។',
  'That is too much text at once. Translate fewer items.': 'អត្ថបទច្រើនពេកក្នុងពេលតែមួយ។ សូមបកប្រែធាតុតិចជាងនេះ។',
