  'Your plan is added: {goals} goal(s), {steps} step(s) and {tasks} task(s).': 'ផែនការរបស់អ្នកត្រូវបានបន្ថែម៖ គោលដៅ {goals} ជំហាន {steps} និងកិច្ចការ {tasks}។',
