  'Complex step "{step}" has no tasks yet.': 'ជំហានស្មុគស្មាញ "{step}" មិនទាន់មានកិច្ចការទេ។',
  'A new task under "{step}" needs a title.': 'កិច្ចការថ្មីក្រោម "{step}" ត្រូវការចំណងជើង។',
  'Task "{task}" needs an owner.': 'កិច្ចការ "{task}" ត្រូវការអ្នកទទួលខុសត្រូវ។',
  'Task "{task}" needs a date.': 'កិច្ចការ "{task}" ត្រូវការកាលបរិច្ឆេទ។',
  'Task "{task}" is due after its step.': 'កិច្ចការ "{task}" ផុតកំណត់ក្រោយជំហានរបស់វា។',
