  'Nothing could move without going past its step or goal date. Change the dates or hours yourself.': 'គ្មានអ្វីអាចផ្លាស់បានដោយមិនហួសកាលបរិច្ឆេទជំហាន ឬគោលដៅទេ។ សូមប្តូរកាលបរិច្ឆេទ ឬម៉ោងដោយខ្លួនឯង។',
