  'This task is dated in the past.': 'កិច្ចការនេះមានកាលបរិច្ឆេទកន្លងផុតហើយ។',
  'This task is due after its step.': 'កិច្ចការនេះផុតកំណត់ក្រោយជំហានរបស់វា។',
  'Unable to check your draft.': 'មិនអាចពិនិត្យសេចក្តីព្រាងរបស់អ្នកបានទេ។',
  'Unable to save your hours.': 'មិនអាចរក្សាទុកម៉ោងរបស់អ្នកបានទេ។',
