  'Use the goal\'s date for now, or pick an earlier one.': 'ប្រើកាលបរិច្ឆេទរបស់គោលដៅសិន ឬជ្រើសរើសមួយមុនជាងនេះ។',
  'Use the step\'s date for now, or pick an earlier one.': 'ប្រើកាលបរិច្ឆេទរបស់ជំហានសិន ឬជ្រើសរើសមួយមុនជាងនេះ។',
  'Use {date}': 'ប្រើ {date}',
  'Used for goal, step and task suggestions, helpers and risks, and plan checks. A stronger model builds better plans; a cheaper one stretches the budget.': 'ប្រើសម្រាប់ការណែនាំគោលដៅ ជំហាន និងកិច្ចការ អ្នកជួយ និងហានិភ័យ និងការពិនិត្យផែនការ។ ម៉ូដែលខ្លាំងជាងកសាងផែនការបានល្អជាង ម៉ូដែលថោកជាងជួយសន្សំថវិកា។',
