  'Applied to your draft.': 'បានអនុវត្តទៅសេចក្តីព្រាងរបស់អ្នក។',
  'Saved to your plan.': 'បានរក្សាទុកក្នុងផែនការរបស់អ្នក។',
  'Helping with: {topic}': 'កំពុងជួយ៖ {topic}',
  'Keep this topic when I move to another section': 'រក្សាប្រធានបទនេះ ពេលខ្ញុំទៅផ្នែកផ្សេង',
  'What this section needs': 'អ្វីដែលផ្នែកនេះត្រូវការ',
  'Plan check for this section': 'ការពិនិត្យផែនការសម្រាប់ផ្នែកនេះ',
  'No problems found in this section.': 'រកមិនឃើញបញ្ហាក្នុងផ្នែកនេះទេ។',
  'AI help is not available right now. The help and plan check above still work.': 'ជំនួយ AI មិនអាចប្រើបាននៅពេលនេះទេ។ ជំនួយ និងការពិនិត្យផែនការខាងលើនៅតែដំណើរការ។',
  'Suggested changes': 'ការផ្លាស់ប្តូរដែលបានណែនាំ',
  'Suggest changes': 'ណែនាំការផ្លាស់ប្តូរ',
  'No changes to suggest for this section.': 'គ្មានការផ្លាស់ប្តូរត្រូវណែនាំសម្រាប់ផ្នែកនេះទេ។',
  'Apply to draft': 'អនុវត្តទៅសេចក្តីព្រាង',
