  'A dashed bar end means the date was worked out from related records, not entered. Hatching shows the part that runs past what it belongs to. Select a bar to edit it.': 'ចុងរបារជាដាច់ៗ មានន័យថាកាលបរិច្ឆេទត្រូវបានគណនាពីកំណត់ត្រាពាក់ព័ន្ធ មិនមែនបានបញ្ចូលទេ។ ឆ្នូតបង្ហាញផ្នែកដែលលើសពីអ្វីដែលវាជាកម្មសិទ្ធិ។ ជ្រើសរបារមួយដើម្បីកែសម្រួល។',
